from typing import List

def f(m: int, n: int, probabilities: List[List[float]]) -> float:
    if m == 1:
        return max(probabilities[0])
    else:
        combined_probabilities = []
        for i in range(n):
            combined_probability = probabilities[0][i]
            for j in range(1, m):
                combined_probability *= probabilities[j][i]
            combined_probabilities.append(combined_probability)

        return round(max(combined_probabilities), 3)
```

